import json
from pathlib import Path
base=Path('/home/ubuntu/university_research')
old={s['domain']:s for s in json.load(open(base/'parts/us_research.json'))['schools']}
master={s['domain']:s for s in json.load(open(base/'deliverables/research_classified.json'))['schools']}
S={}
for dom in old:
 m=master[dom]
 S[dom]={k:m[k] for k in ['short_name','name','domain']}
 S[dom].update(ai_portals=[],items=[],search_note_vi='Mẫu chọn lọc 2 công trình có phương pháp AI cụ thể; không phải toàn bộ danh mục AI của trường hoặc xếp hạng chất lượng. Đối chiếu nguồn chính thức ngày 30/10/2026.')
def portal(dom,title,url):S[dom]['ai_portals'].append(dict(title=title,url=url))
def add(dom,title,year,typ,venue,authors,aff,url,doi,summary,problem,method,codes,apps,sources,depth='abstract_and_metadata',status='published',note='',existing=False,**extra):
 d=dict(title=title,year=year,type=typ,status=status,publication_venue=venue,authors=authors,affiliation=aff,url=url,doi=doi,summary_vi=summary,problem_vi=problem,ai_method_vi=method,reading_depth=depth,verification_note=note or 'Đã đọc tóm tắt và thông tin công bố; chưa đánh giá toàn văn hoặc khả năng tái lập.',source_urls=list(dict.fromkeys([url]+sources)),ai_topic_codes=codes,application_domains=apps,full_text_read=False,checked_on='2026-10-30',source_relation='existing_enriched' if existing else 'new_targeted_search')
 d.update(extra);S[dom]['items'].append(d)
def olditem(dom,idx,**kw):
 i=old[dom]['items'][idx]
 vals=dict(dom=dom,title=i['title'],year=i['year'],typ=i['type'],aff=i['university_attribution'],url=i.get('publication_url') or i['url'],doi=i['doi'],summary=i['summary_vi'],sources=i['source_urls'],note=i['verification_note'],existing=True)
 vals.update(kw);add(**vals)
